  [13163] = { "Il Cacciatore assume l'aspetto di una scimmia, aumentando la probabilità di schivata del $N1%. Può essere attivo un solo aspetto alla volta.", "Aumenta la probabilità di schivata del $N1%.", 0xe1104e48, 0xc8a06f5b, "uu" },
